"""Release (MTP-1 WP12, report 8.4 items iii and iv): "the results tables and figures, regenerated by a single command", and the benchmark
with its datasheet, in one folder that says what it was made from and can be checked later.

A release is made from a RECIPE (configs/release_template.json): the grid, the benchmark, the freeze manifest, the run folders of the case
studies, the files you write by hand (the prose of the paper, the commentary of the case studies). `build` runs the whole chain on finished
runs, offline:

    freeze check -> Table 4 + paired tests + figures -> case studies -> benchmark + datasheet -> paper draft -> RELEASE.md, SHA256SUMS.txt,
    release_manifest.json

and writes it into one folder:

    RELEASE.md  FREEZE.json  freeze_verify.txt  SHA256SUMS.txt  release_manifest.json
    inputs/  (the recipe and copies of the hand-written files)   tables/   case_studies/   benchmark/   paper/

`verify FOLDER` does two things: it checks that no file of the folder was changed after the build, and it builds the release again from the
recipe into a temporary folder and compares every file. Same runs + same inputs => the same files (figures are compared too, but a
difference in a PNG alone is a warning, because the image encoder is not part of this repository). A source file that changed after the
release (more prose, new commentary, a run that was added) shows up as a difference under inputs/, which is the point.

Nothing is run and no API call is made. The files you write by hand are never modified: the release works on copies. Making a release does
not make the results right: it shows what they were made from and that they can be made again. See scripts/release.py.
"""
import datetime
import hashlib
import json
import os
import re
import shutil
import subprocess
import tempfile

from capp import benchmark as B, casestudy as C, config, dataset, freeze, paperdraft as P, tables as T

FORMAT = 1
MANIFEST = "release_manifest.json"
SUMS = "SHA256SUMS.txt"
OWNED_DIRS = ("inputs", "tables", "case_studies", "benchmark", "paper")
OWNED_FILES = ("RELEASE.md", "FREEZE.json", "freeze_verify.txt", SUMS, MANIFEST)
TEXT_SUFFIXES = (".md", ".csv", ".tex", ".txt", ".json")
SOFT_SUFFIXES = (".png",)
RECIPE_KEYS = ("name", "grid", "results", "freeze", "benchmark", "text", "case_studies", "extraction", "notes")
CASE_KEYS = ("runs", "commentary", "per_type", "types", "instructive")
DEFAULT_TEXT = "paper/paper_text.json"
NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,59}$")
EXPECTED_TAGS = ("baseline-v0", "freeze-v1")


class ReleaseError(ValueError):
    pass


# ---------------------------------------------------------------- recipe
def _text(v) -> bool:
    return isinstance(v, str) and bool(v.strip())


def normalise_recipe(raw, where: str = "recipe") -> dict:
    """The recipe with every key present. Raises ReleaseError naming every problem at once. normalise(normalise(x)) == normalise(x)."""
    if not isinstance(raw, dict):
        raise ReleaseError(f"{where}: expected a JSON object")
    bad = []
    unknown = sorted(set(raw) - set(RECIPE_KEYS) - {"_comment"})
    if unknown:
        bad.append(f"unknown key(s) {unknown} (known: {', '.join(RECIPE_KEYS)})")
    R = {}
    if not (isinstance(raw.get("name"), str) and NAME_RE.match(raw["name"])):
        bad.append("name: letters, digits, '.', '_' and '-' only (at most 60), e.g. \"mtp1_final\"")
    R["name"] = raw.get("name")
    if not _text(raw.get("grid")):
        bad.append("grid: the ablation config of the final runs is required (configs/final.json)")
    R["grid"] = raw.get("grid")
    for key in ("results", "freeze", "benchmark"):
        v = raw.get(key)
        if v is not None and not _text(v):
            bad.append(f"{key}: a path or null")
        R[key] = v
    R["text"] = raw.get("text", DEFAULT_TEXT)
    if not _text(R["text"]):
        bad.append("text: the path of the file with your prose (default " + DEFAULT_TEXT + ")")
    ex = raw.get("extraction", [])
    if not isinstance(ex, list) or not all(_text(e) for e in ex) or len(set(ex)) != len(ex):
        bad.append("extraction: a list of different run folders (or empty)")
        ex = []
    R["extraction"] = list(ex)
    R["notes"] = raw.get("notes", "")
    if not isinstance(R["notes"], str):
        bad.append("notes: a string")
    cs = raw.get("case_studies")
    if cs is None:
        R["case_studies"] = None
    elif not isinstance(cs, dict):
        bad.append("case_studies: an object {runs, commentary, per_type, types, instructive} or null")
        R["case_studies"] = None
    else:
        extra = sorted(set(cs) - set(CASE_KEYS))
        if extra:
            bad.append(f"case_studies: unknown key(s) {extra} (known: {', '.join(CASE_KEYS)})")
        runs = cs.get("runs")
        if not isinstance(runs, list) or not runs or not all(_text(r) for r in runs) or len(set(runs)) != len(runs):
            bad.append("case_studies.runs: a non-empty list of different run folders")
            runs = []
        com = cs.get("commentary")
        if com is not None and not _text(com):
            bad.append("case_studies.commentary: a path or null")
        per = cs.get("per_type", C.DEFAULT_PER_TYPE)
        if isinstance(per, bool) or not isinstance(per, int) or not 1 <= per <= 10:
            bad.append("case_studies.per_type: an integer from 1 to 10")
            per = C.DEFAULT_PER_TYPE
        types = cs.get("types")
        if types is not None:
            try:
                types = C.validate_types(types if isinstance(types, list) else [None])
            except C.CaseError as exc:
                bad.append(f"case_studies.types: {exc}")
                types = None
        inst = cs.get("instructive", [])
        if not isinstance(inst, list) or not all(isinstance(t, str) for t in inst):
            bad.append("case_studies.instructive: a list of \"PART[:REPEAT[:SAMPLE]]=WHY\"")
            inst = []
        else:
            for t in inst:
                try:
                    C.parse_instructive(t)
                except C.CaseError as exc:
                    bad.append(f"case_studies.instructive: {exc}")
        R["case_studies"] = {"runs": list(runs), "commentary": com, "per_type": per, "types": types, "instructive": list(inst)}
    if bad:
        raise ReleaseError(f"{where}: " + "; ".join(bad))
    return R


def load_recipe(path: str) -> dict:
    try:
        with open(path, encoding="utf-8") as f:
            raw = json.load(f)
    except OSError as exc:
        raise ReleaseError(f"recipe {path} cannot be read: {exc}")
    except ValueError as exc:
        raise ReleaseError(f"recipe {path} is not valid JSON: {exc}")
    return normalise_recipe(raw, path)


def _abs(root: str, p: str) -> str:
    return p if os.path.isabs(p) else os.path.join(root, p)


def _posix(p: str) -> str:
    return str(p).replace("\\", "/")


def inputs(R: dict, root: str) -> list:
    """What the recipe names: [{'what', 'path', 'abs', 'required', 'exists'}]. A run folder exists when it has records.jsonl."""
    want = [("grid", R["grid"], True, "file"), ("freeze manifest", R["freeze"] or freeze.MANIFEST_NAME, False, "file"),
            ("prose", R["text"], False, "file")]
    if R["benchmark"]:
        want.append(("benchmark", R["benchmark"], True, "file"))
    cs = R["case_studies"]
    if cs:
        want += [("case-study run", r, True, "run") for r in cs["runs"]]
        if cs["commentary"]:
            want.append(("case commentary", cs["commentary"], False, "file"))
    want += [("extraction run", e, True, "run") for e in R["extraction"]]
    out = []
    for what, path, required, kind in want:
        a = _abs(root, path)
        exists = os.path.isfile(os.path.join(a, "records.jsonl")) if kind == "run" else os.path.isfile(a)
        out.append({"what": what, "path": _posix(path), "abs": a, "required": required, "exists": exists})
    return out


# ---------------------------------------------------------------- check
def check(recipe_path: str, root: str = None) -> dict:
    """What a build would find, without writing anything: the inputs, the freeze status, how many runs of the grid are usable."""
    root = os.path.abspath(root or str(config.ROOT))
    R = load_recipe(recipe_path)
    ins = inputs(R, root)
    res = {"recipe": R, "inputs": ins, "missing": [i for i in ins if i["required"] and not i["exists"]], "grid": None, "grid_error": None,
           "freeze": None}
    fr = next(i for i in ins if i["what"] == "freeze manifest")
    if fr["exists"]:
        res["freeze"] = freeze.status(root, fr["abs"])
    grid = next(i for i in ins if i["what"] == "grid")
    if grid["exists"]:
        try:
            cfg = T.load_config(grid["abs"])
            an = T.analyse(cfg, _abs(root, R["results"]) if R["results"] else None)
            built = sum(1 for r in cfg["rows"] if r["system"] is not None)
            res["grid"] = {"name": cfg["name"], "dataset": cfg["dataset"], "sealed": P.is_final(cfg), "models": len(cfg["models"]),
                           "rows": len(cfg["rows"]), "built": built, "cells": built * len(cfg["models"]), "usable": len(an["usable"])}
        except T.TableError as exc:
            res["grid_error"] = str(exc)
    return res


def format_check(c: dict) -> str:
    R = c["recipe"]
    L = [f"Recipe {R['name']}", ""]
    for i in c["inputs"]:
        mark = "ok" if i["exists"] else ("MISSING" if i["required"] else "not there yet")
        L.append(f"  [{mark:>13}] {i['what']:<16} {i['path']}")
    g = c["grid"]
    L.append("")
    if g:
        L.append(f"Grid {g['name']}: dataset {g['dataset']} ({'sealed' if g['sealed'] else 'development'}), {g['models']} LLM(s), "
                 f"{g['built']}/{g['rows']} rows built, {g['usable']}/{g['cells']} runs usable")
    elif c["grid_error"]:
        L.append(f"Grid: {c['grid_error']}")
    f = c["freeze"]
    L.append("Freeze: " + (f"{f['status']} ({f['id']})" if f else "no manifest found"))
    L.append("")
    L.append(f"{len(c['missing'])} required input(s) missing: build would stop." if c["missing"] else "All required inputs are there: build can run.")
    return "\n".join(L)


# ---------------------------------------------------------------- small file helpers
def _write(path: str, text: str):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def _copy_text(src: str, dst: str):
    """A text file copied with LF line endings, so a Windows checkout and a Linux one give the same hash."""
    with open(src, encoding="utf-8", newline="") as f:
        _write(dst, f.read().replace("\r\n", "\n"))


def _sha(path: str) -> str:
    with open(path, "rb") as f:
        data = f.read()
    if path.lower().endswith(TEXT_SUFFIXES):
        data = data.replace(b"\r\n", b"\n")
    return hashlib.sha256(data).hexdigest()


def _list_files(base: str) -> list:
    out = []
    for d in OWNED_DIRS:
        for dp, dn, fn in os.walk(os.path.join(base, d)):
            dn.sort()
            out += [_posix(os.path.relpath(os.path.join(dp, f), base)) for f in sorted(fn)]
    out += [f for f in OWNED_FILES if f != MANIFEST and os.path.isfile(os.path.join(base, f))]
    return sorted(out)


def _git_tags(root: str) -> list:
    try:
        r = subprocess.run(["git", "tag", "-l"], cwd=root, capture_output=True, text=True, timeout=10)
        return r.stdout.split() if r.returncode == 0 else []
    except Exception:
        return []


# ---------------------------------------------------------------- the chain
def _stable(message: str, *prefixes) -> str:
    """A message with the folders of this machine taken out (the temporary build folder, the repository), so that the same release built
    on another machine, or by `verify`, gives the same text."""
    for p in sorted({os.path.abspath(x) for x in prefixes}, key=len, reverse=True):
        for sep in (os.sep, "/"):
            message = message.replace(p + sep, "")
        message = message.replace(p, ".")
    return message


def _make(R: dict, tmp: str, root: str, figures: bool) -> dict:
    ins = {i["what"]: i for i in inputs(R, root)}
    info = {"steps": [], "freeze": None}
    grid_abs = ins["grid"]["abs"]
    results_abs = _abs(root, R["results"]) if R["results"] else None

    # inputs: the recipe and copies of what is written by hand
    _write(os.path.join(tmp, "inputs", "recipe.json"), json.dumps(R, indent=2, ensure_ascii=False, sort_keys=True) + "\n")
    _copy_text(grid_abs, os.path.join(tmp, "inputs", "grid.json"))
    text_copy = os.path.join(tmp, "inputs", "paper_text.json")
    if ins["prose"]["exists"]:
        _copy_text(ins["prose"]["abs"], text_copy)
    if "case commentary" in ins and ins["case commentary"]["exists"]:
        _copy_text(ins["case commentary"]["abs"], os.path.join(tmp, "inputs", "case_commentary.json"))

    # freeze
    fr = ins["freeze manifest"]
    freeze_path = fr["abs"] if (fr["exists"] or R["freeze"]) else None      # a named manifest that is missing is reported by the draft
    if fr["exists"]:
        try:
            ver = freeze.verify(root, fr["abs"])
            _copy_text(fr["abs"], os.path.join(tmp, "FREEZE.json"))
            _write(os.path.join(tmp, "freeze_verify.txt"), freeze.format_comparison(ver) + "\n")
            info["freeze"] = {"id": ver["id"], "status": ver["status"]}
        except freeze.FreezeError as exc:
            info["freeze"] = {"id": None, "status": "unreadable", "error": str(exc)}
    info["steps"].append(("freeze", "no manifest" if not info["freeze"] else f"{info['freeze']['status']} ({info['freeze']['id']})"))

    # tables
    cfg = T.load_config(grid_abs)
    tables = T.build(cfg, os.path.join(tmp, "tables"), results_abs, figures)
    built = sum(1 for r in cfg["rows"] if r["system"] is not None)
    info["cfg"], info["cells"], info["usable"] = cfg, built * len(cfg["models"]), len(tables["usable"])
    info["steps"].append(("tables", f"{len(tables['files'])} files, {info['usable']}/{info['cells']} runs usable"))

    # case studies
    case_dir = None
    cs = R["case_studies"]
    if cs:
        runs = [C.load_run(ins_["abs"]) for ins_ in inputs(R, root) if ins_["what"] == "case-study run"]
        labels = [r["label"] for r in runs]
        if len(set(labels)) != len(labels):
            raise ReleaseError(f"two case-study runs have the same folder name {sorted({x for x in labels if labels.count(x) > 1})}")
        com = {}
        if "case commentary" in ins and ins["case commentary"]["exists"]:
            com = C.read_commentary(ins["case commentary"]["abs"])
        res = C.analyse(runs, types=cs["types"] or C.DEFAULT_TYPES, per_type=cs["per_type"],
                        instructive=[C.parse_instructive(t) for t in cs["instructive"]], commentary=com)
        C.write_outputs(res, os.path.join(tmp, "case_studies"))
        case_dir = os.path.join(tmp, "case_studies")
        info["cases"] = {"n": len(res["cases"]), "no_commentary": res["n_without_commentary"]}
        info["steps"].append(("case studies", f"{len(res['cases'])} case(s), {res['n_without_commentary']} without commentary"))

    # benchmark
    bench_abs = None
    if R["benchmark"]:
        bench_abs = ins["benchmark"]["abs"]
        _copy_text(bench_abs, os.path.join(tmp, "benchmark", os.path.basename(bench_abs)))
        sibling = os.path.splitext(bench_abs)[0] + "_datasheet.md"
        if os.path.isfile(sibling):
            _copy_text(sibling, os.path.join(tmp, "benchmark", "DATASHEET.md"))
            info["datasheet"] = "the datasheet written at import"
        else:
            try:
                bparts = dataset.load_dataset(bench_abs, validate=False)
                sheet = B.datasheet(bparts, None, B.agreement(bparts), generated="")
            except (OSError, ValueError, KeyError, TypeError) as exc:
                raise ReleaseError(f"benchmark {_posix(R['benchmark'])} cannot be read ({exc}): there is no datasheet next to it to use")
            _write(os.path.join(tmp, "benchmark", "DATASHEET.md"), sheet.rstrip() + "\n")
            info["datasheet"] = "regenerated from the benchmark file (no import report: no conflicts section)"
        info["steps"].append(("benchmark", f"{os.path.basename(bench_abs)} + DATASHEET.md ({info['datasheet']})"))

    # paper draft
    ctx = P.collect(grid_abs, bench_abs, case_dir, [ins_["abs"] for ins_ in inputs(R, root) if ins_["what"] == "extraction run"],
                    freeze_path, os.path.join(tmp, "tables"), results_abs, root)
    ctx["problems"] = [_stable(m, tmp, root) for m in ctx["problems"]]       # no machine-specific path in a file that is compared later
    ctx["bench_path"], ctx["config_path"] = R["benchmark"] and _posix(R["benchmark"]), _posix(R["grid"])
    ctx["reproduce"] = ["python scripts/release.py build <recipe>     # the recipe is inputs/recipe.json", "python scripts/release.py verify <this folder>"]
    paper = P.write_all(ctx, text_copy, os.path.join(tmp, "paper"))
    info["paper"], info["ctx"] = paper, ctx
    blocking = [c for c in paper["checks"] if c["level"] == "blocking" and not c["ok"]]
    info["steps"].append(("paper draft", "READY" if paper["ready"] else f"NOT READY: {len(blocking)} blocking item(s)"))
    return info


def _release_md(R: dict, info: dict) -> str:
    cfg, paper, fr = info["cfg"], info["paper"], info["freeze"]
    blocking = [c for c in paper["checks"] if c["level"] == "blocking" and not c["ok"]]
    advisory = [c for c in paper["checks"] if c["level"] == "advisory" and not c["ok"]]
    final = P.is_final(cfg)
    L = [f"# Release: {R['name']}", ""]
    if not final:
        L += [f"> **DEVELOPMENT RESULTS, NOT PAPER RESULTS.** The grid `{cfg['name']}` runs on the development set `{cfg['dataset']}`: this folder "
              "is a rehearsal of the release.", ""]
    elif blocking:
        L += [f"> **NOT READY.** {len(blocking)} blocking item(s) below: the numbers in this folder are not yet final results.", ""]
    L += ["Made by `python scripts/release.py build <recipe>` (the recipe is `inputs/recipe.json`). "
          "Check it later with `python scripts/release.py verify <this folder>`: it tests that no file changed since the build and that building "
          "again from the same sources gives the same files.", ""]
    if R["notes"].strip():
        L += [R["notes"].strip(), ""]
    notes = {"RELEASE.md": "this file", "FREEZE.json": "the freeze manifest: the configuration, pinned before the first run on the sealed set",
             "freeze_verify.txt": "whether the working tree still matched the freeze when this was built",
             SUMS: "SHA-256 of every file here except release_manifest.json (text files with LF line endings)",
             MANIFEST: "the build record: time, commit, file hashes (not part of the comparison in `verify`)",
             "inputs/": "the recipe and copies of the files written by hand (prose, case commentary), so the folder says what it was made from",
             "tables/": "Table 4 (md, csv, tex), paired comparisons, consistency across LLMs, per-part results, issues, figures (`scripts/make_tables.py`)",
             "case_studies/": "the failure case studies of the report, 7.5 (`scripts/case_studies.py`)",
             "benchmark/": "the expert benchmark and its datasheet", "paper/": "`paper_draft.md` (facts and your prose) and `readiness.txt`"}
    later = ("RELEASE.md", SUMS, MANIFEST)                       # written after this text is made
    present = [k for k in notes if k in later or os.path.exists(os.path.join(info["tmp"], k.rstrip("/")))]
    L += ["## Contents", "", "| path | what |", "|---|---|"] + [f"| `{k}` | {notes[k]} |" for k in present] + [""]
    L += ["## What it was made from", ""]
    L.append(f"- Grid `{R['grid']}` (`{cfg['name']}`): dataset `{cfg['dataset']}` ({'sealed' if final else 'development'}), {len(cfg['models'])} LLM(s), "
             f"{sum(1 for r in cfg['rows'] if r['system'] is not None)}/{len(cfg['rows'])} rows built, {info['usable']}/{info['cells']} runs usable.")
    L.append("- Freeze: " + (f"`{fr['id']}`, status **{fr['status']}** when this was built." if fr and fr.get("id") else
                             "the manifest could not be read." if fr else "no manifest (`FREEZE.json`): the configuration is not pinned."))
    if R["benchmark"]:
        L.append(f"- Benchmark `{_posix(R['benchmark'])}`; datasheet: {info['datasheet']}.")
    if info.get("cases"):
        L.append(f"- Case studies: {info['cases']['n']} case(s), {info['cases']['no_commentary']} without commentary.")
    if R["extraction"]:
        L.append("- Extraction runs (M9): " + ", ".join(f"`{_posix(e)}`" for e in R["extraction"]) + ".")
    L += ["", "## Readiness of the numbers", ""]
    L.append("Ready: every blocking item of `paper/readiness.txt` is closed." if paper["ready"] else
             f"Not ready: {len(blocking)} blocking item(s) open.")
    L += [f"- [BLOCKING] {c['message']}" for c in blocking] + [f"- [advisory] {c['message']}" for c in advisory] + [""]
    L += ["## Before you publish it", "",
          "```", "python -m pytest", "python scripts/freeze.py verify", "python scripts/release.py verify <this folder>",
          "git tag baseline-v0 <commit of the internship code>    # once, if it is not there yet (see BASELINE.md)",
          "git tag freeze-v1                                     # the commit with FREEZE.json, made before the first run on the sealed set",
          f"git add <this folder>; git commit -m \"Release {R['name']}\"; git tag release-{R['name']}", "git push origin --tags", "```", "",
          "## What this does not show", "",
          "- `verify` shows that the folder is what the recipe and the inputs produce. It does not show that the inputs are right: the runs, the "
          "prose, the benchmark annotation and the case commentary are yours.",
          "- The freeze shows that the files are the ones that were pinned. It does not show that no test result was seen before it was made.",
          "- A release built from a development grid is a rehearsal, not a result.", ""]
    return "\n".join(L)


def _install(tmp: str, out: str):
    if os.path.isdir(out):
        for d in OWNED_DIRS:
            shutil.rmtree(os.path.join(out, d), ignore_errors=True)
        for f in OWNED_FILES:
            if os.path.isfile(os.path.join(out, f)):
                os.remove(os.path.join(out, f))
    else:
        os.makedirs(out)
    for item in sorted(os.listdir(tmp)):
        shutil.move(os.path.join(tmp, item), os.path.join(out, item))


def build(recipe_path: str, out_dir: str, root: str = None, figures: bool = True, now: str = None) -> dict:
    """Builds the release folder. The files are made in a temporary folder next to out_dir and moved in at the end, so a failure leaves a
    previous release untouched. A folder that is not empty and is not a release (no release_manifest.json) is refused. Returns
    {'out', 'files' {path: sha256}, 'ready', 'checks', 'steps', 'freeze', 'git', 'tags', 'manifest'}."""
    root = os.path.abspath(root or str(config.ROOT))
    R = load_recipe(recipe_path)
    missing = [f"{i['what']} {i['path']}" for i in inputs(R, root) if i["required"] and not i["exists"]]
    if missing:
        raise ReleaseError("required input(s) not found: " + ", ".join(missing))
    out_dir = os.path.abspath(out_dir)
    if os.path.isfile(out_dir):
        raise ReleaseError(f"{out_dir} is a file")
    if os.path.isdir(out_dir) and os.listdir(out_dir) and not os.path.isfile(os.path.join(out_dir, MANIFEST)):
        raise ReleaseError(f"{out_dir} is not empty and is not a release folder (no {MANIFEST}): choose another --out")
    parent = os.path.dirname(out_dir)
    os.makedirs(parent, exist_ok=True)
    tmp = tempfile.mkdtemp(prefix=".release-", dir=parent)
    try:
        info = _make(R, tmp, root, figures)
        info["tmp"] = tmp
        _write(os.path.join(tmp, "RELEASE.md"), _release_md(R, info))
        files = _list_files(tmp)
        sums = {f: _sha(os.path.join(tmp, f)) for f in files}
        _write(os.path.join(tmp, SUMS), "".join(f"{h}  {f}\n" for f, h in sorted(sums.items())))
        sums[SUMS] = _sha(os.path.join(tmp, SUMS))
        git = freeze.git_info(root)
        tags = _git_tags(root)
        paper = info["paper"]
        blocking = [c for c in paper["checks"] if c["level"] == "blocking" and not c["ok"]]
        manifest = {"format": FORMAT, "name": R["name"], "created_utc": now or datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                    "git": git, "tags": tags, "figures": bool(figures), "dataset": info["cfg"]["dataset"], "sealed": P.is_final(info["cfg"]),
                    "freeze": info["freeze"], "ready": paper["ready"], "blocking": [c["message"] for c in blocking], "files": dict(sorted(sums.items()))}
        _write(os.path.join(tmp, MANIFEST), json.dumps(manifest, indent=2, ensure_ascii=False) + "\n")
        _install(tmp, out_dir)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    return {"out": out_dir, "files": manifest["files"], "ready": paper["ready"], "checks": paper["checks"], "steps": info["steps"],
            "freeze": info["freeze"], "git": git, "tags": tags, "manifest": manifest}


# ---------------------------------------------------------------- verify
def load_manifest(release_dir: str) -> dict:
    path = os.path.join(release_dir, MANIFEST)
    try:
        with open(path, encoding="utf-8") as f:
            man = json.load(f)
    except OSError as exc:
        raise ReleaseError(f"{path} cannot be read ({exc}): not a release folder")
    except ValueError as exc:
        raise ReleaseError(f"{path} is not valid JSON: {exc}")
    if not isinstance(man, dict) or man.get("format") != FORMAT or not isinstance(man.get("files"), dict):
        raise ReleaseError(f"{path}: not a release manifest of format {FORMAT}")
    return man


def verify(release_dir: str, root: str = None, regenerate: bool = True) -> dict:
    """{'ok', 'modified', 'missing', 'extra', 'regen'}: no file changed since the build; and (regenerate) building again from the recipe in
    inputs/ gives the same files. regen = {'differs', 'figures', 'only_release', 'only_now'} or None."""
    root = os.path.abspath(root or str(config.ROOT))
    rd = os.path.abspath(release_dir)
    man = load_manifest(rd)
    modified, missing = [], []
    for rel, h in man["files"].items():
        p = os.path.join(rd, rel)
        if not os.path.isfile(p):
            missing.append(rel)
        elif _sha(p) != h:
            modified.append(rel)
    extra = sorted(set(_list_files(rd)) - set(man["files"]))
    regen = None
    if regenerate:
        recipe = os.path.join(rd, "inputs", "recipe.json")
        if not os.path.isfile(recipe):
            raise ReleaseError(f"{recipe} is missing: the release cannot be rebuilt")
        with tempfile.TemporaryDirectory() as t:
            now = build(recipe, os.path.join(t, "release"), root, man.get("figures", True), now=man.get("created_utc"))["files"]
        before = man["files"]
        differs = sorted(f for f in before if f in now and before[f] != now[f])
        hard = [f for f in differs if not f.lower().endswith(SOFT_SUFFIXES)]
        soft = [f for f in differs if f.lower().endswith(SOFT_SUFFIXES)]
        only_release, only_now = sorted(set(before) - set(now)), sorted(set(now) - set(before))
        others = [f for f in hard if f != SUMS]
        if SUMS in hard and (others or soft or only_release or only_now):      # the sums file lists every file: it only follows their differences
            hard = others
        regen = {"differs": hard, "figures": soft, "only_release": only_release, "only_now": only_now}
    ok = not (modified or missing or extra) and (regen is None or not (regen["differs"] or regen["only_release"] or regen["only_now"]))
    return {"ok": ok, "name": man.get("name"), "created_utc": man.get("created_utc"), "modified": sorted(modified), "missing": sorted(missing),
            "extra": extra, "regen": regen, "files": len(man["files"])}


def format_verify(v: dict) -> str:
    L = [f"Release {v['name']} (built {v['created_utc']}): {v['files']} files", ""]
    L.append("Files unchanged since the build." if not (v["modified"] or v["missing"] or v["extra"]) else "Files changed since the build:")
    for title, items in (("modified", v["modified"]), ("missing", v["missing"]), ("not in the manifest", v["extra"])):
        L += [f"  {title}: {f}" for f in items]
    r = v["regen"]
    if r is None:
        L.append("Rebuild: skipped (--no-regenerate).")
    elif not (r["differs"] or r["only_release"] or r["only_now"]):
        L.append("Rebuilt from the recipe: every file is identical." + (f" ({len(r['figures'])} figure(s) differ in bytes only: warning.)" if r["figures"] else ""))
    else:
        L.append("Rebuilt from the recipe, and it is not the same:")
        L += [f"  differs: {f}" for f in r["differs"]] + [f"  only in the release: {f}" for f in r["only_release"]] + [f"  only in the rebuild: {f}" for f in r["only_now"]]
        if any(f.startswith("inputs/") for f in r["differs"] + r["only_now"] + r["only_release"]):
            L.append("  (a difference under inputs/ means a source file changed after the release: the prose, the commentary, the grid or a run)")
        if r["figures"]:
            L.append(f"  {len(r['figures'])} figure(s) also differ in bytes (warning only).")
    L += ["", "VERIFIED" if v["ok"] else "NOT VERIFIED"]
    return "\n".join(L)
